use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

/// Rate limiter with sliding window
pub struct RateLimiter {
    windows: Mutex<HashMap<String, Vec<Instant>>>,
    max_requests: usize,
    window_duration: Duration,
}

impl RateLimiter {
    pub fn new(max_requests: usize, window_secs: u64) -> Self {
        RateLimiter {
            windows: Mutex::new(HashMap::new()),
            max_requests,
            window_duration: Duration::from_secs(window_secs),
        }
    }

    pub fn check_rate_limit(&self, key: &str) -> bool {
        let mut windows = self.windows.lock().unwrap();
        let now = Instant::now();
        let entry = windows.entry(key.to_string()).or_insert_with(Vec::new);
        entry.retain(|t| now.duration_since(*t) < self.window_duration);
        if entry.len() >= self.max_requests {
            return false;
        }
        entry.push(now);
        true
    }
}

/// Represents a resolved endpoint for OIDC discovery
#[derive(Clone, Debug)]
pub struct OidcEndpoint {
    pub issuer: String,
    pub token_endpoint: String,
    pub userinfo_endpoint: String,
}

/// Validates that a URL is safe to fetch (no internal networks)
fn is_safe_url(url: &str) -> bool {
    let parsed = match url::Url::parse(url) {
        Ok(u) => u,
        Err(_) => return false,
    };

    // Must be HTTPS
    if parsed.scheme() != "https" {
        return false;
    }

    // Block private/internal IPs
    if let Some(host) = parsed.host_str() {
        if host == "localhost" || host == "127.0.0.1" || host == "::1" {
            return false;
        }
        if host.starts_with("10.") || host.starts_with("192.168.") {
            return false;
        }
        if host.starts_with("172.") {
            if let Some(second_octet) = host.split('.').nth(1) {
                if let Ok(n) = second_octet.parse::<u8>() {
                    if n >= 16 && n <= 31 {
                        return false;
                    }
                }
            }
        }
        // Block metadata endpoints
        if host == "169.254.169.254" {
            return false;
        }
    }

    true
}

/// Resolves the final URL after following redirects, with retry logic
/// Returns the resolved URL that will be used for the actual request
fn resolve_with_retry(
    client: &reqwest::blocking::Client,
    url: &str,
    max_retries: u32,
) -> Result<String, String> {
    let mut attempts = 0;
    let mut current_url = url.to_string();

    loop {
        if attempts >= max_retries {
            return Err("Max retries exceeded".to_string());
        }
        attempts += 1;

        // Validate the URL before each request attempt
        if !is_safe_url(&current_url) {
            return Err(format!("URL blocked by security policy: {}", current_url));
        }

        let response = client
            .get(&current_url)
            .send()
            .map_err(|e| format!("Request failed: {}", e))?;

        match response.status().as_u16() {
            200 => return Ok(current_url),
            301 | 302 | 307 | 308 => {
                if let Some(location) = response.headers().get("location") {
                    let loc_str = location.to_str().map_err(|e| format!("Invalid header: {}", e))?;
                    // Resolve relative URLs against current
                    let base = url::Url::parse(&current_url).map_err(|e| format!("Parse error: {}", e))?;
                    let resolved = base.join(loc_str).map_err(|e| format!("Join error: {}", e))?;
                    current_url = resolved.to_string();
                    // Note: safety check happens at top of loop
                } else {
                    return Err("Redirect without Location header".to_string());
                }
            }
            429 => {
                // Rate limited by upstream, retry after backoff
                std::thread::sleep(Duration::from_millis(100 * attempts as u64));
                // Don't change URL, just retry
            }
            503 => {
                // Service unavailable, retry
                std::thread::sleep(Duration::from_millis(200 * attempts as u64));
            }
            _ => return Err(format!("Unexpected status: {}", response.status())),
        }
    }
}

/// OIDC Discovery: fetches the well-known configuration
pub fn discover_oidc_config(
    rate_limiter: &RateLimiter,
    client: &reqwest::blocking::Client,
    issuer_url: &str,
    client_id: &str,
) -> Result<OidcEndpoint, String> {
    // Rate limit per client
    if !rate_limiter.check_rate_limit(client_id) {
        return Err("Rate limit exceeded".to_string());
    }

    // Validate the issuer URL
    if !is_safe_url(issuer_url) {
        return Err("Issuer URL blocked by security policy".to_string());
    }

    let well_known = format!("{}/.well-known/openid-configuration", issuer_url.trim_end_matches('/'));

    // Resolve with retries (handles transient failures and redirects)
    let final_url = resolve_with_retry(client, &well_known, 5)?;

    // Fetch the actual configuration from the resolved URL
    let resp = client
        .get(&final_url)
        .send()
        .map_err(|e| format!("Config fetch failed: {}", e))?;

    let body: serde_json::Value = resp
        .json()
        .map_err(|e| format!("JSON parse failed: {}", e))?;

    let token_endpoint = body["token_endpoint"]
        .as_str()
        .ok_or("Missing token_endpoint")?
        .to_string();

    let userinfo_endpoint = body["userinfo_endpoint"]
        .as_str()
        .ok_or("Missing userinfo_endpoint")?
        .to_string();

    Ok(OidcEndpoint {
        issuer: issuer_url.to_string(),
        token_endpoint,
        userinfo_endpoint,
    })
}

/// Exchange authorization code for tokens
pub fn exchange_code(
    rate_limiter: &RateLimiter,
    client: &reqwest::blocking::Client,
    endpoint: &OidcEndpoint,
    code: &str,
    client_id: &str,
    client_secret: &str,
    redirect_uri: &str,
) -> Result<serde_json::Value, String> {
    if !rate_limiter.check_rate_limit(client_id) {
        return Err("Rate limit exceeded".to_string());
    }

    // Use the token endpoint from discovery - validate it
    let token_url = &endpoint.token_endpoint;
    let resolved_token_url = resolve_with_retry(client, token_url, 3)?;

    let resp = client
        .post(&resolved_token_url)
        .form(&[
            ("grant_type", "authorization_code"),
            ("code", code),
            ("client_id", client_id),
            ("client_secret", client_secret),
            ("redirect_uri", redirect_uri),
        ])
        .send()
        .map_err(|e| format!("Token exchange failed: {}", e))?;

    resp.json().map_err(|e| format!("Token parse failed: {}", e))
}
